func (s *StateStore) list(ctx context.Context, strict bool) ([]*State, error) {
	if err := ctx.Err(); err != nil {
		return nil, fmt.Errorf("list session states: %w", err)
	}
	root, err := s.dirRoot()
	if err != nil {
		return nil, fmt.Errorf("failed to open session state directory: %w", err)
	}
	entries, err := osroot.ReadDirNoSymlinks(root, s.dirName)
	if os.IsNotExist(err) {
		return nil, nil
	}
	if err != nil {
		return nil, fmt.Errorf("failed to read session state directory: %w", err)
	}

	var states []*State
	for _, entry := range entries {
		if err := ctx.Err(); err != nil {
			return nil, fmt.Errorf("list session states: %w", err)
		}
		if !strings.HasSuffix(entry.Name(), ".json") {
			continue
		}
		if entry.IsDir() {
			if strict {
				return nil, fmt.Errorf("session state %s is a directory", entry.Name())
			}
			continue
		}
		if strings.HasSuffix(entry.Name(), ".tmp") {
			continue // Skip temp files
		}

		sessionID := strings.TrimSuffix(entry.Name(), ".json")
		state, err := s.Load(ctx, sessionID)
		if err != nil {
			if strict {
				return nil, fmt.Errorf("load session %s: %w", sessionID, err)
			}
			continue
		}
		if state == nil {
			continue // Not found or stale (Load handles cleanup)
		}

		states = append(states, state)
	}
	return states, nil
}

