	head, err := repo.Head()
	if err != nil {
		return false, false, fmt.Errorf("failed to get HEAD: %w", err)
	}

	currentHead := head.Hash().String()
	if state.BaseCommit == currentHead {
		return false, false, nil // No migration needed
	}

